display.text:
:root {
  --ink-0: #07090c;
  --ink-1: #0d1117;
  --ink-2: #151b23;
  --line: #2a3441;
  --line-strong: #46566a;
  --text: #e8edf2;
  --muted: #9ba8b8;
  --cost: #ffbf47;
  --queued: #8793a1;
  --running: #43b9ff;
  --done: #57d38c;
  --failed: #ff6470;
  --timeout: #c995ff;
  --unknown: #aab3be;
  --sans: system-ui, -apple-system, "Segoe UI", sans-serif;
  --mono: ui-monospace, "SFMono-Regular", Consolas, monospace;
}

* {
  box-sizing: border-box;
}

html {
  background: var(--ink-0);
  color-scheme: dark;
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 0;
  overflow: hidden;
  background: var(--ink-0);
  color: var(--text);
  font-family: var(--sans);
  font-size: 14px;
}

button,
input,
summary {
  font: inherit;
}

button,
summary {
  min-height: 36px;
}

button {
  border: 1px solid var(--line-strong);
  border-radius: 3px;
  background: var(--ink-2);
  color: var(--text);
  cursor: pointer;
}

button:hover:not(:disabled),
summary:hover {
  border-color: var(--text);
  background: #1b2430;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.52;
}

button:focus-visible,
input:focus-visible,
summary:focus-visible,
a:focus-visible,
[tabindex]:focus-visible {
  outline: 2px solid var(--running);
  outline-offset: 2px;
}

[hidden] {
  display: none !important;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.app-shell {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto auto;
  height: 100dvh;
  min-width: 0;
}

